-- AKP = jumlah janjang / jumlah pokok TM / rotasi dalam sebulan. Rotasi = HA_PANEN (blok TM, jumlah harian) / Ha TM bulan itu. Kolom: jjg, pokok, hap (ha panen TM), hatm (ha TM). Janjang hanya dari blok TM (INT_HEKTAR_BLOK pada bulan panen).
-- Hasil -> work/r_akp.json {"BAAFD": {"jjg":[n bulan],"pk":[n bulan]}}
WITH blk AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, KODE_AFD afd, KODE_BLOK blok, DATE_TRUNC('month',BULAN)::DATE mo, MAX(IFF(MATURITY_STATUS='TM' AND KATEGORI_TANAH='PLANTED',1,0)) tm, SUM(IFF(MATURITY_STATUS='TM' AND KATEGORI_TANAH='PLANTED',COALESCE(JML_POKOK,0),0)) pk, SUM(IFF(MATURITY_STATUS='TM' AND KATEGORI_TANAH='PLANTED',COALESCE(HEKTAR,0),0)) ha FROM PRD_DB_INTEGRATION.INT_PANEN.INT_HEKTAR_BLOK WHERE KODE_BA IN ('2121','2124','2131','2122') AND BULAN>='2026-01-01' AND BULAN<'2026-10-01' GROUP BY 1,2,3,4),
pk AS (SELECT ba, afd, TO_CHAR(mo,'YYYY-MM') m, SUM(pk) pokok, SUM(ha) hatm FROM blk GROUP BY 1,2,3),
jj AS (SELECT DECODE(p.KODE_BA,'2122','2131',p.KODE_BA) ba, p.KODE_AFD afd, TO_CHAR(DATE_TRUNC('month',p.TANGGAL_PANEN),'YYYY-MM') m, SUM(IFF(b.tm=1,p.JJG_AKTUAL,0)) jjg, SUM(IFF(b.tm=1,p.HA_PANEN,0)) hap FROM PRD_DB_INTEGRATION.INT_PANEN.INT_PENCAPAIAN_PRODUKSI_PANEN p LEFT JOIN blk b ON b.ba=DECODE(p.KODE_BA,'2122','2131',p.KODE_BA) AND b.afd=p.KODE_AFD AND b.blok=p.KODE_BLOK AND b.mo=DATE_TRUNC('month',p.TANGGAL_PANEN)::DATE WHERE p.KODE_BA IN ('2121','2124','2131','2122') AND p.TANGGAL_PANEN>='2026-01-01' AND p.TANGGAL_PANEN<'2026-10-01' GROUP BY 1,2,3)
SELECT pk.ba, pk.afd, pk.m, ROUND(COALESCE(jj.jjg,0)) jjg, ROUND(pk.pokok) pokok, ROUND(COALESCE(jj.hap,0),1) hap, ROUND(pk.hatm,1) hatm FROM pk LEFT JOIN jj ON jj.ba=pk.ba AND jj.afd=pk.afd AND jj.m=pk.m WHERE NOT (pk.ba='2131' AND pk.afd='B') AND pk.pokok>0 ORDER BY 1,2,3
